#include <stdint.h>
#include <string.h>
#include <gpiodriver.h>
#include <stm32f407xx.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif
/* ************************************************
 * MACROS
 * *********************************************** */


/* ************************************************
 * Global Structures
 * *********************************************** */

GPIO_Handler_t orangeLED, button;

int main(void)
{
	memset(&orangeLED, 0, sizeof(GPIO_Handler_t));
	memset(&button, 0, sizeof(GPIO_Handler_t));

	// Enable Clock for Port D
	GPIO_CLKControl(GPIOA, ENABLE);

	// Enable Clock for Port D
	GPIO_CLKControl(GPIOD, ENABLE);

	button.pGPIOBaseAddr = GPIOA;

	button.GPIOPinConfig.pinNumber = GPIO_PIN_0;
	button.GPIOPinConfig.pinMode = GPIO_MODE_IN;
	button.GPIOPinConfig.pinSpeed = GPIO_OUTPUT_SPEED_HIGH;
	button.GPIOPinConfig.pinPullUpPullDown = GPIO_NO_PULL_UP_DOWN;

	orangeLED.pGPIOBaseAddr = GPIOD;
	orangeLED.GPIOPinConfig.pinNumber = GPIO_PIN_13;
	orangeLED.GPIOPinConfig.pinMode = GPIO_MODE_OUT;
	orangeLED.GPIOPinConfig.pinOutputType = GPIO_OUTPUT_TYPE_PUSHPULL;
	orangeLED.GPIOPinConfig.pinSpeed = GPIO_OUTPUT_SPEED_MEDIUM;
	orangeLED.GPIOPinConfig.pinPullUpPullDown = GPIO_NO_PULL_UP_DOWN;

	GPIO_Init(&orangeLED);
	GPIO_Init(&button);
    /* Loop forever */
	volatile uint32_t i;
	uint8_t readValue;
	for(;;)
	{
		readValue = GPIO_ReadPortPin(GPIOA, GPIO_PIN_0);
		for(i=0;i<80000;i++); // Added a delay for reducing switch debouncing
		if(readValue != GPIO_CLEAR_PIN)
		{
			GPIO_WritePortPin(GPIOD, orangeLED.GPIOPinConfig.pinNumber, GPIO_SET_PIN);
		}
		else
		{
			GPIO_WritePortPin(GPIOD, orangeLED.GPIOPinConfig.pinNumber, GPIO_CLEAR_PIN);
		}
	}
}
